-- =====================================================================
-- POKEGAMES — Pokédex em português
-- 151 descrições originais, escritas para o jogo (sem o nome do Pokémon).
-- Rode UMA vez no SQL Editor. Substitui as descrições em outros idiomas.
-- A importação de imagens no Admin não mexe mais nas descrições.
-- =====================================================================
on conflict (pokemon_id) do update set description = excluded.description, updated_at = now();

select count(*) as descricoes_em_portugues from public.pokemon_media where description is not null;
