insert into public.pokemon_media (pokemon_id, description) values
(1, $d$Carrega nas costas uma semente que cresce junto com ele e guarda a energia do sol para os dias difíceis.$d$),
(2, $d$O botão nas suas costas ficou tão pesado que ele já não consegue ficar de pé sobre duas patas. Passa horas tomando sol para que ele desabroche.$d$),
(3, $d$Uma flor enorme se abre nas suas costas. O perfume dela acalma quem está por perto, e as folhas largas absorvem a luz do sol.$d$),
(4, $d$A chama na ponta da cauda mostra como ele está: forte quando está saudável, fraca quando está cansado. Se ela se apagar, a vida dele corre perigo.$d$),
(5, $d$Tem pavio curto e adora uma briga. Quando se irrita, a chama da cauda fica tão quente que chega a mudar de cor.$d$),
(6, $d$Voa pelos céus procurando adversários à altura. Seu fogo derrete pedras, mas ele nunca usa as chamas contra quem é mais fraco.$d$),
(7, $d$Quando se sente ameaçado, recolhe o corpo dentro do casco e contra-ataca com jatos de água pela boca.$d$),
(8, $d$A cauda felpuda é considerada um sinal de vida longa. As orelhas cobertas de pelo o ajudam a se equilibrar quando nada.$d$),
(9, $d$Dois canhões saem do seu casco e disparam jatos de água com força para atravessar placas de metal.$d$),
(10, $d$Pequena lagarta verde de pés com ventosas. Quando assustada, solta um cheiro forte pela antena vermelha da cabeça.$d$),
(11, $d$Fica parado dentro de uma casca verde e dura enquanto o corpo mole se transforma por dentro. Quase não se mexe.$d$),
(12, $d$Suas asas são cobertas por um pó que pode causar sono, paralisia ou envenenamento. Voa de flor em flor atrás de néctar.$d$),
(13, $d$Larva pequena e peluda com um ferrão venenoso no alto da cabeça. Vive escondida entre as folhas da floresta.$d$),
(14, $d$Casulo amarelo pendurado nos galhos. Por fora parece imóvel, mas pode soltar o ferrão para se defender.$d$),
(15, $d$Vive em enxames e defende o ninho com fúria. Tem dois ferrões enormes nas patas dianteiras e outro na ponta do corpo.$d$),
(16, $d$Pássaro pequeno, dócil e muito comum nos campos. Prefere fugir a brigar, levantando poeira com as asas para despistar.$d$),
(17, $d$Defende um território grande e voa em círculos atento a qualquer invasor. Agarra as presas com garras afiadas.$d$),
(18, $d$Tem uma crista longa e colorida na cabeça. Voa sobre o mar a uma velocidade impressionante para caçar.$d$),
(19, $d$Roedor roxo que vive em qualquer lugar. Os dentes da frente nunca param de crescer, então ele rói tudo o que encontra.$d$),
(20, $d$Os bigodes o ajudam a manter o equilíbrio. Os dentes grandes conseguem roer até concreto.$d$),
(21, $d$Pássaro pequeno e briguento. Bate as asas bem rápido para voar baixo e defender seu território aos gritos.$d$),
(22, $d$Pescoço e bico compridos, perfeitos para pegar presas na terra e na água. Consegue voar um dia inteiro sem pousar.$d$),
(23, $d$Serpente roxa que se enrola em silêncio e engole ovos de pássaros inteiros. O chocalho da cauda avisa quando ataca.$d$),
(24, $d$O desenho na sua barriga parece um rosto ameaçador, e ele usa isso para assustar inimigos antes do bote.$d$),
(25, $d$Guarda eletricidade nas bochechas vermelhas. Quando se sente ameaçado ou fica animado, solta faíscas.$d$),
(26, $d$Quando acumula eletricidade demais, fica nervoso e descarrega o excesso pela cauda longa, em forma de raio.$d$),
(27, $d$Vive em regiões secas e arenosas. Quando se assusta, enrola o corpo e vira uma bola de casca dura.$d$),
(28, $d$As costas são cobertas de espinhos duros. Enrola-se como uma bola espinhosa e rola para cima do inimigo.$d$),
(29, $d$Pequena, azulada e tranquila. Mesmo pacífica, tem farpas venenosas pelo corpo para se defender.$d$),
(30, $d$Quando está com a família ou com amigos, recolhe os espinhos para não machucar ninguém. Fica nervosa longe do grupo.$d$),
(31, $d$Tem o corpo coberto de escamas duras como uma armadura. Protege seus filhotes com uma força assustadora.$d$),
(32, $d$Mexe as orelhas grandes para ouvir longe. O chifre da testa solta um veneno poderoso.$d$),
(33, $d$Temperamento agressivo. O chifre é mais duro que diamante e libera veneno quando acerta.$d$),
(34, $d$Sua cauda grossa é tão forte que derruba uma árvore com um só golpe. Rosna e avança sem medo.$d$),
(35, $d$Criatura rosada e adorável, vista dançando em círculos em noites de lua cheia no alto das montanhas.$d$),
(36, $d$Tímido e raro, quase nunca aparece para as pessoas. Sua audição é tão boa que ouve passos a quilômetros.$d$),
(37, $d$Nasce com uma única cauda branca, que se divide em várias conforme ele cresce. O pelo ruivo é muito macio.$d$),
(38, $d$Dizem que vive por mil anos. Suas várias caudas douradas guardam um poder misterioso.$d$),
(39, $d$Olhos grandes e corpo redondo. Canta uma canção de ninar que faz qualquer um cair no sono.$d$),
(40, $d$Corpo macio e elástico que infla quando respira fundo. O pelo é tão fofo que todos querem abraçá-lo.$d$),
(41, $d$Não tem olhos. Solta ondas sonoras para se orientar no escuro das cavernas onde vive em bandos.$d$),
(42, $d$Boca enorme com presas afiadas. Ataca à noite e voa sem parar, mesmo de barriga cheia.$d$),
(43, $d$De dia fica enterrado no chão, só com as folhas para fora. À noite sai andando e espalha suas sementes.$d$),
(44, $d$Solta um líquido de cheiro horrível pela boca. Pouquíssimas pessoas gostam do aroma.$d$),
(45, $d$Tem as maiores pétalas do mundo. A cada passo, espalha um pólen que causa alergia e envenena.$d$),
(46, $d$Cogumelos crescem nas suas costas e se alimentam dos nutrientes do corpo dele. Vive em lugares úmidos.$d$),
(47, $d$O cogumelo nas costas cresceu tanto que passou a controlar o corpo. Prefere a escuridão das matas fechadas.$d$),
(48, $d$Seus olhos grandes funcionam como radares. É ativo à noite e é atraído pela luz.$d$),
(49, $d$Mariposa de asas cobertas de um pó tóxico. Quando bate as asas, o pó se espalha no ar.$d$),
(50, $d$Vive debaixo da terra e só põe a cabeça para fora. Os túneis que cava deixam o solo bom para plantar.$d$),
(51, $d$Três cabeças que cavam juntas, tão rápido que fazem a terra tremer.$d$),
(52, $d$Adora coisas brilhantes e sai à noite procurando moedas. Tem uma moeda dourada presa na testa.$d$),
(53, $d$Felino elegante com uma joia vermelha na testa. É orgulhoso, de temperamento difícil e muito ágil.$d$),
(54, $d$Vive com dor de cabeça. Quando ela fica forte demais, solta poderes psíquicos sem perceber.$d$),
(55, $d$Nada com agilidade incrível usando as patas com membranas. Tem uma joia vermelha na testa.$d$),
(56, $d$Macaco de pelo claro que se irrita por qualquer coisa. Num instante passa da calma à fúria.$d$),
(57, $d$Sua raiva é tão grande que não para de perseguir o inimigo até alcançá-lo.$d$),
(58, $d$Cão leal e corajoso. Late e rosna para proteger seu território e seu treinador.$d$),
(59, $d$Cão majestoso de pelagem listrada, presente em lendas antigas. Corre longas distâncias como se voasse.$d$),
(60, $d$Tem uma espiral desenhada na barriga e pele tão fina que quase dá para ver o que há por dentro.$d$),
(61, $d$Vive tanto na água quanto na terra. Quando está fora da água, transpira para manter o corpo úmido.$d$),
(62, $d$Nadador excelente e lutador de músculos fortes. Atravessa oceanos inteiros a nado.$d$),
(63, $d$Dorme a maior parte do dia. Se sente perigo, se teletransporta para longe, mesmo dormindo.$d$),
(64, $d$Segura uma colher que amplifica seus poderes psíquicos. Quem fica perto dele pode sentir dor de cabeça.$d$),
(65, $d$Tem um cérebro enorme e uma memória que nunca falha. Leva uma colher em cada mão.$d$),
(66, $d$Treina o corpo o tempo todo. Mesmo pequeno, levanta pessoas adultas sem esforço.$d$),
(67, $d$Usa um cinto especial para controlar a força descomunal dos seus músculos.$d$),
(68, $d$Tem quatro braços musculosos que desferem uma chuva de socos em poucos segundos.$d$),
(69, $d$Corpo fino como um caule e cabeça em forma de botão. Prende insetos com as folhas.$d$),
(70, $d$Planta em forma de sino que derrama um ácido forte em quem chega perto demais.$d$),
(71, $d$Atrai as presas com um aroma doce e as engole inteiras dentro da boca enorme.$d$),
(72, $d$Corpo quase transparente como uma água-viva. Flutua no mar e ferroa com os tentáculos.$d$),
(73, $d$Tem dezenas de tentáculos venenosos que esticam e encolhem. As esferas vermelhas da cabeça brilham.$d$),
(74, $d$Parece uma pedra redonda com dois braços. Vive em trilhas de montanha e às vezes é pisado sem querer.$d$),
(75, $d$Desce as montanhas rolando e não se importa com os pedaços de rocha que perde no caminho.$d$),
(76, $d$Coberto por uma casca de rocha duríssima. Uma vez por ano troca essa casca, que cresce de novo.$d$),
(77, $d$Cavalo de crina e cauda de fogo. Ao nascer ainda é fraco, mas em pouco tempo corre muito rápido.$d$),
(78, $d$Galopa a uma velocidade incrível com a crina em chamas. Adora desafiar outros corredores.$d$),
(79, $d$Extremamente lento e distraído. Usa a cauda como isca para pescar na beira dos rios.$d$),
(80, $d$Uma concha mordeu sua cauda e ficou presa nela. Desde então ele ficou ainda mais lento.$d$),
(81, $d$Ímã flutuante que se alimenta de eletricidade. É atraído por fios e postes de energia.$d$),
(82, $d$Três unidades unidas por magnetismo. Costuma aparecer quando há tempestades magnéticas.$d$),
(83, $d$Pássaro marrom que sempre carrega um talo de planta, usado como arma e como ferramenta.$d$),
(84, $d$Ave de duas cabeças que não voa, mas corre muito. As duas cabeças pensam de forma diferente.$d$),
(85, $d$Tem três cabeças, e cada uma parece sentir uma emoção diferente. Corre em alta velocidade pelas planícies.$d$),
(86, $d$Vive em mares gelados. Usa a protuberância da cabeça para quebrar o gelo e nadar por baixo.$d$),
(87, $d$Pelagem branca e grossa que aguenta frio intenso. Adora dormir sobre blocos de gelo.$d$),
(88, $d$Massa de lodo tóxico que surgiu da sujeira. Por onde passa, deixa um rastro de gosma.$d$),
(89, $d$Corpo de lodo fedorento. As plantas murcham por onde ele passa.$d$),
(90, $d$Molusco de concha dupla e dura. Costuma deixar a língua comprida para fora.$d$),
(91, $d$A concha é duríssima e cheia de espinhos. Dispara esses espinhos contra quem se aproxima.$d$),
(92, $d$Corpo feito de gás. Envolve as vítimas e as faz desmaiar sem que percebam.$d$),
(93, $d$Gosta de se esconder no escuro. Lambe suas vítimas com uma língua feita de gás que dá calafrios.$d$),
(94, $d$Esconde-se na sombra das pessoas. Quando ele está por perto, o ambiente fica frio de repente.$d$),
(95, $d$Serpente gigante formada por rochas. Cava túneis debaixo da terra em grande velocidade.$d$),
(96, $d$Faz as pessoas dormirem e se alimenta dos sonhos delas. O nariz comprido sente cheiro de sonho bom.$d$),
(97, $d$Carrega um pêndulo que balança para hipnotizar quem olhar para ele.$d$),
(98, $d$Caranguejo da praia com pinças fortes. Se perde uma pinça, outra cresce no lugar.$d$),
(99, $d$Uma das pinças é gigante e pesada, com força enorme, mas difícil de mover com rapidez.$d$),
(100, $d$Esfera vermelha e branca que lembra um item de captura. Explode ao menor toque.$d$),
(101, $d$Guarda tanta energia que explode com facilidade. Também é chamado de bomba-relógio.$d$),
(102, $d$Seis sementes que parecem ovos e se comunicam por telepatia. Se uma se afasta, as outras vão buscá-la.$d$),
(103, $d$Parece uma palmeira que anda. Tem várias cabeças, e cada uma pensa por conta própria.$d$),
(104, $d$Usa um crânio como capacete e nunca o tira. Dizem que chora à noite com saudade.$d$),
(105, $d$Arremessa um osso como bumerangue com grande precisão. Ficou forte e corajoso com o tempo.$d$),
(106, $d$As pernas se esticam muito para desferir chutes poderosos a distância.$d$),
(107, $d$Lutador que dá socos em velocidade incrível, como um campeão de boxe.$d$),
(108, $d$Tem uma língua enorme, duas vezes maior que o corpo, e lambe tudo para conhecer as coisas.$d$),
(109, $d$Balão de gases tóxicos que flutua. Pode explodir se ficar cheio demais.$d$),
(110, $d$Dois corpos unidos, cheios de gás venenoso. Quanto mais sujo o ar, mais feliz ele fica.$d$),
(111, $d$Corre sempre em linha reta derrubando o que encontra. Muitas vezes esquece por que começou a correr.$d$),
(112, $d$Anda sobre duas patas e tem um chifre em forma de broca que perfura rochas.$d$),
(113, $d$Carrega na bolsa da barriga um ovo muito nutritivo e o divide com quem está ferido.$d$),
(114, $d$Corpo inteiro coberto de cipós azuis que balançam. Ninguém sabe ao certo como é por baixo deles.$d$),
(115, $d$Mãe protetora que carrega o filhote numa bolsa na barriga e o defende a qualquer custo.$d$),
(116, $d$Pequeno cavalo-marinho que dispara tinta preta pela boca para escapar dos predadores.$d$),
(117, $d$Tem espinhos venenosos nas barbatanas. É o macho que cuida dos ovos.$d$),
(118, $d$Peixe elegante com um chifre na testa e nadadeiras que parecem véus. Nada contra a correnteza.$d$),
(119, $d$Usa o chifre para cavar ninhos nas pedras do rio. Na época de desova, as cores ficam mais vivas.$d$),
(120, $d$Estrela-do-mar com uma joia brilhante no centro, que pisca à noite. Regenera as pontas que perde.$d$),
(121, $d$Seu núcleo brilha em várias cores. Há quem diga que ele veio do espaço.$d$),
(122, $d$Mímico talentoso que cria paredes invisíveis apenas com gestos das mãos.$d$),
(123, $d$Inseto verde com braços em forma de foice. É tão rápido que parece sumir.$d$),
(124, $d$Move o corpo como se estivesse dançando e fala numa língua que parece humana, mas ninguém entende.$d$),
(125, $d$É atraído por usinas de energia e costuma causar apagões nas cidades.$d$),
(126, $d$Corpo envolto em chamas. Costuma ser encontrado perto de vulcões.$d$),
(127, $d$Tem duas pinças enormes na cabeça que esmagam o que agarram. Não gosta do frio.$d$),
(128, $d$Touro de três caudas. Chicoteia o próprio corpo com elas antes de investir.$d$),
(129, $d$Peixe fraco e desajeitado que só sabe pular. Mesmo assim, é encontrado em quase toda água.$d$),
(130, $d$Serpente marinha enorme e furiosa. Quando se irrita, destrói tudo ao seu redor.$d$),
(131, $d$Gentil e inteligente, leva pessoas nas costas pelo mar. Gosta de cantar.$d$),
(132, $d$Pode copiar a forma de qualquer coisa que vê, mas nem sempre acerta o rosto.$d$),
(133, $d$Seus genes instáveis permitem que evolua de formas diferentes, dependendo do ambiente.$d$),
(134, $d$Sua pele lembra a água, e ele consegue sumir dentro dela. Tem barbatanas e cauda de peixe.$d$),
(135, $d$Os pelos se eriçam como agulhas carregadas de eletricidade quando ele fica bravo.$d$),
(136, $d$Guarda chamas dentro do corpo e solta o calor pelo pelo fofo do pescoço.$d$),
(137, $d$Criado inteiramente por programação. Consegue entrar e se mover dentro de computadores.$d$),
(138, $d$Fóssil revivido de um molusco antigo com concha em espiral. Nadava movendo os tentáculos.$d$),
(139, $d$A concha ficou tão pesada que ele mal conseguia caçar. Os tentáculos agarram a presa com força.$d$),
(140, $d$Fóssil revivido de uma criatura que vivia no fundo do mar. Os olhos brilham no escuro.$d$),
(141, $d$Tem braços em forma de foice e caçava nadando rapidamente. Dizem que saiu do mar para a terra.$d$),
(142, $d$Réptil voador pré-histórico, revivido a partir de material genético preso em âmbar.$d$),
(143, $d$Come centenas de quilos por dia e dorme logo depois. Às vezes bloqueia estradas inteiras.$d$),
(144, $d$Ave lendária de gelo. Dizem que aparece para viajantes perdidos nas montanhas nevadas.$d$),
(145, $d$Ave lendária que controla a eletricidade. Vive entre as nuvens de tempestade.$d$),
(146, $d$Ave lendária de fogo. Quando bate as asas, espalha faíscas e chamas pelo céu.$d$),
(147, $d$Serpente rara que troca de pele várias vezes enquanto cresce. Vive em águas profundas.$d$),
(148, $d$Serpente elegante capaz de mudar o clima. Tem joias no pescoço e na cauda.$d$),
(149, $d$Dragão gentil que dá a volta ao mundo voando e ajuda náufragos a voltar para casa.$d$),
(150, $d$Criado por cientistas a partir de genes. Tem poderes psíquicos imensos e um coração frio.$d$),
(151, $d$Raríssimo. Dizem que carrega o código genético de todos os outros e que pode ficar invisível.$d$)
